package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class UTF8JsonGenerator_writeBinary_TriageGen2Test {

    private IOContext ioContext;
    private OutputStream outputStream;
    private UTF8JsonGenerator generator;

    @Before
    public void setUp() {
        ioContext = new IOContext();
        // Using a large enough buffer to avoid immediate flush logic complexity in simple cases, 
        // but we will test the buffer logic via the constructor.
        outputStream = new java.io.ByteArrayOutputStream();
        generator = new UTF8JsonGenerator(ioContext, 0, null, outputStream);
    }

    @Test
    public void testWriteBinary_WithKnownLength_Success() throws IOException {
        byte[] data = {0x01, 0x02, 0x03, 0x04};
        InputStream inputStream = new ByteArrayInputStream(data);

        int bytesWritten = generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, inputStream, data.length);

        Assert.assertEquals(data.length, bytesWritten);

        // Verify output is wrapped in quotes and base64 encoded
        // Base64 for [1,2,3,4] is AQIDBA==
        String result = outputStream.toString();
        Assert.assertEquals("\"AQIDBA==\"", result);
    }

    @Test
    public void testWriteBinary_WithUnknownLength() throws IOException {
        byte[] data = {0x01, 0x02, 0x03, 0x04};
        InputStream inputStream = new ByteArrayInputStream(data);

        // dataLength < 0 triggers the branch for unknown length
        int bytesWritten = generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, inputStream, -1);

        Assert.assertEquals(data.length, bytesWritten);
        String result = outputStream.toString();
        Assert.assertEquals("\"AQIDBA==\"", result);
    }

    @Test(expected = IOException.class)
    public void testWriteBinary_TooFewBytesAvailable_ThrowsException() throws IOException {
        byte[] data = {0x01, 0x02};
        InputStream inputStream = new ByteArrayInputStream(data);

        // Requested 4 bytes but only 2 available
        // This should trigger _reportError which throws an IOException
        generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, inputStream, 4);
    }

    @Test
    public void testWriteBinary_BufferFlushLogic() throws IOException {
        // Create a generator with a very small buffer to force _flushBuffer calls
        byte[] smallBuffer = new byte[2];
        generator = new UTF8JsonGenerator(ioContext, 0, null, outputStream, smallBuffer, 0, false);

        byte[] data = {0x01, 0x02, 0x03, 0x04};
        InputStream inputStream = new ByteArrayInputStream(data);

        // This will trigger _flushBuffer because of the starting quote and the data size
        int bytesWritten = generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, inputStream, data.length);

        Assert.assertEquals(data.length, bytesWritten);
        String result = outputStream.toString();
        Assert.assertEquals("\"AQIDBA==\"", result);
    }

    @Test
    public void testWriteBinary_EmptyData() throws IOException {
        byte[] data = new byte[0];
        InputStream inputStream = new ByteArrayInputStream(data);

        int bytesWritten = generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, inputStream, 0);

        Assert.assertEquals(0, bytesWritten);
        String result = outputStream.toString();
        Assert.assertEquals("\"\"", result);
    }

    @Test(expected = IOException.class)
    public void testWriteBinary_InputStreamThrowsIOException() throws IOException {
        InputStream errorStream = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated failure");
            }
            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                throw new IOException("Simulated failure");
            }
        };

        generator.writeBinary(Base64Variant.INCLUDE_CERT_BASE64, errorStream, 4);
    }
}
